// Pure-gas viscosity and thermal conductivity polynomials
// (viscosity_coefficients.h, thermal_conductivity_coefficients.h, generated by
// scripts/gen_transport_coefficients.py). These tests pin:
//   * every engine component has one row in each table, and each row is an
//     engine component;
//   * every row is positive over the evaluation window;
//   * the NASA rows agree with the NASA CEA transport data (trans.inp; the
//     coefficients are copied below) within 1 % over their data range, and are
//     increasing over the whole window;
//   * a few values at 300 K that the documentation quotes.

#include <algorithm>
#include <cmath>
#include <string>

#include <gtest/gtest.h>

#include "adsim/objects/fluid.h"
#include "adsim/objects/thermal_conductivity_coefficients.h"
#include "adsim/objects/viscosity_coefficients.h"

namespace adsim {
namespace {

enum Property { kViscosity, kConductivity };

// First (lowest-temperature) interval of each species in data/trans.inp of
// NASA CEA (nasa/cea commit 2f79a647e857): ln(eta) = A ln T + B/T + C/T^2 + D,
// eta in micropoise (viscosity) or microwatt/(cm K) (conductivity), valid
// from t0 to 1000 K.
struct NasaInterval {
  const char* component;
  Property property;
  double t0, A, B, C, D;
};

constexpr NasaInterval kNasa[] = {
    {"CarbonMonoxide", kViscosity, 200.0, 0.62526577, -31.779652, -1640.7983, 1.7454992},  // CO
    {"CarbonMonoxide", kConductivity, 200.0, 0.85439436, 105.73224, -12347.848, 0.47793128},  // CO
    {"Ethylene", kViscosity, 200.0, 0.59136053, -140.88938, 3001.28, 1.7018932},  // C2H4
    {"Ethylene", kConductivity, 200.0, 0.2473665, -1058.9987, 89911.568, 6.4456092},  // C2H4
    {"Fluorine", kViscosity, 200.0, 0.61198519, -39.64796, -1729.4474, 2.123771},  // F2
    {"Fluorine", kConductivity, 200.0, 0.46767823, -266.24115, 18169.657, 3.6165585},  // F2
    {"HydrogenSulfide", kConductivity, 300.0, 0.99442135, -198.49376, 18380.943, -0.19947763},  // H2S
    {"Krypton", kViscosity, 200.0, 0.58597795, -129.24832, 4749.5759, 2.579365},  // Kr
    {"Krypton", kConductivity, 200.0, 0.58008139, -137.92556, 6077.146, 1.6420039},  // Kr
    {"Neon", kViscosity, 200.0, 0.68398511, 18.732366, -2366.3189, 1.8284755},  // Ne
    {"Neon", kConductivity, 200.0, 0.68509965, 19.794924, -2452.5539, 2.2586136},  // Ne
    {"NitrousOxide", kViscosity, 200.0, 0.58959112, -155.65178, 3763.0431, 2.1223853},  // N2O
    {"NitrousOxide", kConductivity, 200.0, 0.65165376, -343.73058, 15090.399, 2.4242359},  // N2O
    {"SulfurDioxide", kViscosity, 300.0, 0.53157084, -295.89873, 21224.84, 2.5975549},  // SO2
    {"SulfurDioxide", kConductivity, 300.0, 0.61476551, -564.09295, 49580.787, 2.3940064},  // SO2
    {"Xenon", kViscosity, 200.0, 0.57988418, -188.06666, 10508.723, 2.6502107},  // Xe
    {"Xenon", kConductivity, 200.0, 0.57308328, -199.91432, 12872.027, 1.2718931},  // Xe
};

// SI value of a NASA interval: Pa s or W/(m K).
double NasaValue(const NasaInterval& n, double T) {
  const double eta = std::exp(n.A * std::log(T) + n.B / T + n.C / (T * T) + n.D);
  return n.property == kViscosity ? eta * 1e-7 : eta * 1e-4;
}

double Evaluate(Property p, const std::string& component, double T) {
  return p == kViscosity ? Fluid::GetComponentViscosity(component, T)
                         : Fluid::GetComponentThermalConductivity(component, T);
}

bool IsComponent(const std::string& c) {
  return std::find(Components::componentNames.begin(), Components::componentNames.end(), c) !=
         Components::componentNames.end();
}

}  // namespace

TEST(TransportCoefficients, EveryComponentHasARowInEachTable) {
  for (const auto& c : Components::componentNames) {
    EXPECT_NE(Fluid::ViscosityCoeffs(c), nullptr) << c;
    EXPECT_NE(Fluid::ThermalConductivityCoeffs(c), nullptr) << c;
  }
  for (const auto& [c, k] : kViscosityCoefficients) EXPECT_TRUE(IsComponent(c)) << c;
  for (const auto& [c, k] : kThermalConductivityCoefficients) EXPECT_TRUE(IsComponent(c)) << c;
}

TEST(TransportCoefficients, EveryRowIsPositiveOverTheWindow) {
  for (const auto& c : Components::componentNames) {
    for (double T = Fluid::kViscTmin; T <= Fluid::kViscTmax; T += 1.0) {
      // The raw polynomial, not the floored value of EvalViscosity.
      const auto& v = *Fluid::ViscosityCoeffs(c);
      const auto& k = *Fluid::ThermalConductivityCoeffs(c);
      EXPECT_GT(v[0] + T * (v[1] + T * (v[2] + T * (v[3] + T * v[4]))), 0.0) << c << " at " << T << " K";
      EXPECT_GT(k[0] + T * (k[1] + T * (k[2] + T * (k[3] + T * k[4]))), 0.0) << c << " at " << T << " K";
    }
  }
}

TEST(TransportCoefficients, NasaRowsMatchTheCeaData) {
  for (const auto& n : kNasa) {
    double worst = 0.0, at = 0.0;
    for (double T = n.t0; T <= Fluid::kViscTmax; T += 5.0) {
      const double e = std::abs(Evaluate(n.property, n.component, T) / NasaValue(n, T) - 1.0);
      if (e > worst) worst = e, at = T;
    }
    EXPECT_LT(worst, 0.01) << n.component << (n.property == kViscosity ? " viscosity" : " conductivity")
                           << ": " << 100 * worst << " % at " << at << " K";
  }
}

TEST(TransportCoefficients, NasaRowsIncreaseOverTheWindow) {
  for (const auto& n : kNasa) {
    double prev = 0.0;
    for (double T = Fluid::kViscTmin; T <= Fluid::kViscTmax; T += 1.0) {
      const double v = Evaluate(n.property, n.component, T);
      EXPECT_GT(v, prev) << n.component << " at " << T << " K";
      prev = v;
    }
  }
}

// The water values that docs/equation-of-state.md quotes, and the agreement of
// a CoolProp row and NASA data for a permanent gas (argon: Lemmon and Jacobsen
// 2004 against Bich et al. 1990).
TEST(TransportCoefficients, QuotedValues) {
  EXPECT_NEAR(Fluid::GetComponentViscosity("Water", 298.0), 9.7e-6, 0.05e-6);
  EXPECT_NEAR(Fluid::GetComponentThermalConductivity("Water", 298.0), 0.0184, 0.0001);
  const NasaInterval argon_mu{"Argon", kViscosity, 200.0, 0.61205763, -67.714354, 190.4066, 2.1588272};
  const NasaInterval argon_k{"Argon", kConductivity, 200.0, 0.60968928, -70.892249, 584.20624, 1.9337152};
  EXPECT_NEAR(Fluid::GetComponentViscosity("Argon", 300.0) / NasaValue(argon_mu, 300.0), 1.0, 0.01);
  EXPECT_NEAR(Fluid::GetComponentThermalConductivity("Argon", 300.0) / NasaValue(argon_k, 300.0), 1.0, 0.01);
}

}  // namespace adsim
